
/*
 * LeetCode 389: Find the Difference
 *
 * Problem Statement:
 * Given two strings s and t, string t is generated by
 * randomly shuffling s and adding one extra character.
 *
 * Return the extra character.
 *
 * Approach: Bit Manipulation (XOR)
 *
 * Step-by-Step Explanation:
 *
 * 1. Initialize XOR variable with 0.
 *
 * 2. Traverse string s and XOR every character.
 *
 * 3. Traverse string t and XOR every character.
 *
 * 4. Same characters cancel each other because:
 *    a ^ a = 0
 *
 * 5. The remaining character is the extra character.
 *
 * Time Complexity: O(n)
 * Space Complexity: O(1)
 */

class Solution {

    public char findTheDifference(String s, String t) {

        // Step 1: Initialize XOR
        char result = 0;

        // Step 2: XOR all characters of s
        for (int i = 0; i < s.length(); i++) {
            result ^= s.charAt(i);
        }

        // Step 3: XOR all characters of t
        for (int i = 0; i < t.length(); i++) {
            result ^= t.charAt(i);
        }

        // Step 4: Return extra character
        return result;
    }
}
